  ('city-cafe-tacos-au-poulet-avocat-et-cheddar', 'Tacos au poulet, avocat et cheddar', 'Tacos au poulet, avocat et cheddar préparé simplement à la maison, avec des quantités équilibrées et une cuisson adaptée aux ingrédients.', 'été', 'août', 8, null, null, 'déjeuner/dîner', 'salé', null, '2 personnes', 35, 'facile', 'https://images.pexels.com/photos/36498697/pexels-photo-36498697.jpeg?auto=compress&cs=tinysrgb&h=650&w=940', '[{"name":"Avocats","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Cheddar","quantity":"60","unit":"g","canonical":true,"category":"Crèmerie et produits laitiers"},{"name":"Poulet","quantity":"300","unit":"g","canonical":true,"category":"Viandes, poissons et protéines"},{"name":"Pain","quantity":"2","unit":"pièces","canonical":true,"category":"Féculents, pains et céréales"},{"name":"Salade","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Tomates","quantity":"150","unit":"g","canonical":true,"category":"Fruits, légumes et légumineuses"},{"name":"Sel et poivre","quantity":"1","unit":"c. à soupe","canonical":true,"category":"Épicerie, condiments et produits sucrés"}]'::jsonb, '["Préparer les garnitures avocats, cheddar, poulet; laver et essorer les légumes, puis cuire toute protéine crue à cœur dans une poêle chaude.","Mélanger les éléments de sauce et assaisonner. Trancher le pain; le toaster ou le réchauffer à la poêle jusqu’à ce qu’il soit doré.","Monter le sandwich avec la sauce, les éléments chauds puis les légumes frais. Pour un fromage à gratiner, passer 3 à 5 minutes sous le gril.","Couper en deux et servir aussitôt, avec la garniture prévue."]'::jsonb, 'Préparez et pesez les ingrédients avant de commencer; ajustez le temps de cuisson à la taille réelle des morceaux et vérifiez la cuisson avant de servir.', false, true, 'broco-chou', null, null, array['volaille']::text[], array['avocats', 'cheddar', 'poulet']::text[], array['casserole', 'poêle', 'couteau', 'planche à découper']::text[], 'verified'),
