  ('city-cafe-supreme-de-poulet-roti-jus-creme-et-gratin-dauphinois', 'https://images.pexels.com/photos/20150680/pexels-photo-20150680.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-enchiladas-de-poulet-gratinees-au-cheddar', 'https://images.pexels.com/photos/31843929/pexels-photo-31843929.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-brochettes-de-poulet-yakitori', 'https://images.pexels.com/photos/32722820/pexels-photo-32722820.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
  ('city-cafe-poulet-au-beurre-de-cacahuetes-et-lait-de-coco', 'https://images.pexels.com/photos/11381409/pexels-photo-11381409.jpeg?auto=compress&cs=tinysrgb&h=650&w=940'),
